export type PortfolioPhoto = PortfolioItem & { src: string; width: number; height: number };

export const portfolio: PortfolioPhoto[] = items.map((item) => {
  const [width, height] = dimensions[item.slug];
  return { ...item, src: `/images/work/${item.slug}.webp`, width, height };
});

export const galleryPhotos = portfolio.filter((p) => !p.galleryHidden);
export const featuredPhotos = portfolio.filter((p) => p.featured);

export function getPhoto(slug: string | null | undefined): PortfolioPhoto | undefined {
  return slug ? portfolio.find((p) => p.slug === slug) : undefined;
}

export function photosForCategory(category: CategorySlug): PortfolioPhoto[] {
  return galleryPhotos.filter((p) => p.category === category);
}
